+  @Test
+  public void testResultLevelCacheWithMultiplePostAggregators() throws IOException
+  {
+    final ObjectMapper objectMapper = TestHelper.makeJsonMapper();
+    final long timestamp = DateTimes.of("2011-04-01").getMillis();
+
+    for (Granularity granularity : ImmutableList.of(Granularities.ALL, Granularities.DAY)) {
+      final GroupByQuery query = GroupByQuery.builder()
+                                             .setDataSource(QueryRunnerTestHelper.DATA_SOURCE)
+                                             .setQuerySegmentSpec(QueryRunnerTestHelper.FIRST_TO_THIRD)
+                                             .setDimensions(
+                                                 DefaultDimensionSpec.of("channel"),
+                                                 DefaultDimensionSpec.of("cityName")
+                                             )
+                                             .setAggregatorSpecs(QueryRunnerTestHelper.ROWS_COUNT)
+                                             .setPostAggregatorSpecs(
+                                                 new ExpressionPostAggregator(
+                                                     "a2", "rows * 2", null, null, TestExprMacroTable.INSTANCE
+                                                 ),
+                                                 new ExpressionPostAggregator(
+                                                     "a3", "rows * 3", null, null, TestExprMacroTable.INSTANCE
+                                                 )
+                                             )
+                                             .setGranularity(granularity)
+                                             .build();
+      final CacheStrategy<ResultRow, Object, GroupByQuery> strategy =
+          new GroupByQueryQueryToolChest(null).getCacheStrategy(query);
+      final ResultRow result = query.getResultRowHasTimestamp()
+                               ? ResultRow.of(timestamp, "#en.wikipedia", null, 10516, 21032, 31548)
+                               : ResultRow.of("#en.wikipedia", null, 10516, 21032, 31548);
+
+      final Object preparedValue = strategy.prepareForCache(true).apply(result);
+      Assert.assertEquals(
+          Arrays.asList(timestamp, "#en.wikipedia", null, 10516, 21032, 31548),
+          preparedValue
+      );
+
+      final Object fromCacheValue = objectMapper.readValue(
+          objectMapper.writeValueAsBytes(preparedValue),
+          strategy.getCacheObjectClazz()
+      );
+
+      Assert.assertEquals(result, strategy.pullFromCache(true).apply(fromCacheValue));
+    }
+  }
+
